mgr.bytes_needed = 64; // small buffer for fuzzer speed
mgr.init_cb = +[](void *data){ (void)data; };
mgr.deinit_cb = +[](void *data){ (void)data; };
mgr.finalize_cb = +[](void *data){ (void)data; };
