import random
import string
from typing import List

# Generator for valid JavaScript source code bytes suitable for jerry_eval/jerry_parse.
# Ensure no unbounded recursion by tracking a max depth budget for nested constructs.

MAX_SIZE = 4096
MAX_EXPR_DEPTH = 4
MAX_STMT_DEPTH = 3

_ident_start = string.ascii_letters + '_$'
_ident_continue = _ident_start + string.digits


def _ident(r: random.Random, min_len=1, max_len=8) -> str:
    n = r.randint(min_len, max_len)
    s = r.choice(_ident_start)
    for _ in range(n - 1):
        s += r.choice(_ident_continue)
    return s


def _random_number(r: random.Random) -> str:
    choices = [
        lambda: str(r.randint(-1000, 1000)),
        lambda: f"{r.uniform(-1e6, 1e6):.6g}",
        lambda: hex(r.randint(0, 0xFFFF)),
        lambda: f"0b{r.randint(0, 255):b}",
        lambda: f"0o{r.randint(0, 0o7777):o}",
        lambda: "NaN",
        lambda: "+Infinity",
        lambda: "-Infinity",
    ]
    return r.choice(choices)()


def _random_string_literal(r: random.Random) -> str:
    uni_pool = ['α', 'β', 'γ', 'δ', '🙂', '𝛑']
    length = r.randint(0, 20)
    chars = []
    for _ in range(length):
        if r.random() < 0.2:
            chars.append(r.choice(uni_pool))
        else:
            c = r.choice(string.ascii_letters + string.digits + ' _-.,:;!@#$/\\')
            chars.append(c)
    s = ''.join(chars)
    s = s.replace('\\', r'\\').replace('"', r'\"')
    return f'"{s}"'


def _random_bool(r: random.Random) -> str:
    return "true" if r.random() < 0.5 else "false"


def _random_array(r: random.Random, expr_depth: int) -> str:
    n = r.randint(0, 4)
    elems = []
    for _ in range(n):
        elems.append(_random_expr(r, expr_depth - 1))
    trailing = "," if n and r.random() < 0.3 else ""
    return f"[{', '.join(elems)}{trailing}]"


def _random_object(r: random.Random, expr_depth: int, stmt_depth: int) -> str:
    n = r.randint(0, 4)
    props = []
    for _ in range(n):
        key = _ident(r)
        if stmt_depth > 0 and r.random() < 0.25:
            # method
            body = _random_block(r, stmt_depth - 1)
            props.append(f"{key}(){body}")
        else:
            props.append(f"{key}: {_random_expr(r, expr_depth - 1)}")
    return "{" + ", ".join(props) + "}"


def _random_arrow(r: random.Random, expr_depth: int, stmt_depth: int) -> str:
    # if depth is low, return concise form to avoid recursion
    if stmt_depth <= 0 or r.random() < 0.6:
        arg = _ident(r)
        return f"({arg})=>({_random_expr(r, expr_depth - 1)})"
    else:
        arg = _ident(r)
        return f"({arg})=>{{ return {_random_expr(r, expr_depth - 1)}; }}"


def _random_template(r: random.Random, expr_depth: int) -> str:
    parts = ["`",]
    segs = r.randint(1, 2)
    for i in range(segs):
        lit = ''.join(r.choice(string.ascii_letters+" ") for _ in range(r.randint(0, 6)))
        lit = lit.replace('`', '')
        parts.append(lit)
        if i != segs-1 and expr_depth > 0:
            parts.append("${" + _random_expr(r, expr_depth - 1) + "}")
    parts.append("`")
    return ''.join(parts)


def _random_regex(r: random.Random) -> str:
    body = r.choice(["a+", ".*", "[a-z]+", "\\d+", "^foo$", "(ab|cd)"])
    flags = "".join(ch for ch in "gimuy" if r.random() < 0.3)
    return f"/{body}/{flags}"


def _random_expr(r: random.Random, expr_depth: int, stmt_depth: int = 0) -> str:
    # Base cases to avoid recursion
    if expr_depth <= 0:
        return r.choice([
            _random_number(r),
            _random_string_literal(r),
            _random_bool(r),
            "null",
            "undefined",
            "(1+2)",
        ])
    pick = r.random()
    if pick < 0.12:
        return _random_number(r)
    if pick < 0.24:
        return _random_string_literal(r)
    if pick < 0.33:
        return _random_bool(r)
    if pick < 0.45:
        return _random_array(r, expr_depth)
    if pick < 0.57:
        return _random_object(r, expr_depth, stmt_depth)
    if pick < 0.66:
        return _random_arrow(r, expr_depth, stmt_depth)
    if pick < 0.75:
        return _random_template(r, expr_depth)
    if pick < 0.82:
        return _random_regex(r)
    if pick < 0.90 and expr_depth > 1:
        return f"({_random_expr(r, expr_depth - 1)} {r.choice(['+','-','*','/','%','**','|','&','^','<<','>>'])} {_random_expr(r, expr_depth - 1)})"
    # unary
    return f"{r.choice(['!','~','+','-','typeof '])}{_random_expr(r, expr_depth - 1)}"


def _random_var_decl(r: random.Random, expr_depth: int) -> str:
    kind = r.choice(["let", "const", "var"]) if r.random() < 0.8 else "let"
    names = []
    count = r.randint(1, 2)
    for _ in range(count):
        ident = _ident(r)
        if r.random() < 0.85:
            names.append(f"{ident} = {_random_expr(r, expr_depth)}")
        else:
            names.append(ident)
    return f"{kind} " + ", ".join(names) + ";"


def _random_block(r: random.Random, stmt_depth: int) -> str:
    if stmt_depth <= 0:
        return "{ }"
    stmts = []
    for _ in range(r.randint(0, 2)):
        stmts.append(_random_simple_stmt(r, stmt_depth - 1))
    return "{" + (" ".join(stmts)) + "}"


def _random_if(r: random.Random, expr_depth: int, stmt_depth: int) -> str:
    then = _random_block(r, stmt_depth - 1)
    if stmt_depth > 0 and r.random() < 0.5:
        elsep = _random_block(r, stmt_depth - 1)
        return f"if ({_random_expr(r, expr_depth - 1)}) {then} else {elsep}"
    else:
        return f"if ({_random_expr(r, expr_depth - 1)}) {then}"


def _random_try(r: random.Random, expr_depth: int, stmt_depth: int) -> str:
    btry = _random_block(r, stmt_depth - 1)
    cname = _ident(r)
    bcatch = _random_block(r, stmt_depth - 1)
    bfinally = _random_block(r, stmt_depth - 1) if (stmt_depth > 0 and r.random() < 0.5) else ""
    fin = f" finally {bfinally}" if bfinally else ""
    return f"try {btry} catch({cname}) {bcatch}{fin}"


def _random_loop(r: random.Random, expr_depth: int, stmt_depth: int) -> str:
    t = r.random()
    if t < 0.34:
        return f"for (let i=0;i<{r.randint(1,5)};i++) {_random_block(r, stmt_depth - 1)}"
    if t < 0.68:
        return f"while ({_random_expr(r, expr_depth - 1)}) {_random_block(r, stmt_depth - 1)}"
    return f"do {_random_block(r, stmt_depth - 1)} while({_random_expr(r, expr_depth - 1)});"


def _random_func_decl(r: random.Random, expr_depth: int, stmt_depth: int) -> str:
    name = _ident(r)
    # small param list without set for determinism under depth
    params = ",".join([_ident(r) for _ in range(r.randint(0,2))])
    body = []
    k = r.randint(0, 2)
    for _ in range(k):
        body.append(_random_simple_stmt(r, max(0, stmt_depth - 1)))
    if r.random() < 0.7:
        body.append(f"return {_random_expr(r, expr_depth - 1)};")
    return f"function {name}({params}) {{ {' '.join(body)} }}"


def _random_class(r: random.Random, expr_depth: int, stmt_depth: int) -> str:
    cname = _ident(r)
    base = f" extends {_ident(r)}" if (r.random() < 0.2 and stmt_depth > 0) else ""
    methods: List[str] = []
    if r.random() < 0.5:
        methods.append("constructor(a,b) { this.a=a; this.b=b; }")
    for _ in range(r.randint(0, 2)):
        m = _ident(r)
        if r.random() < 0.5:
            methods.append(f"{m}() {{ return {_random_expr(r, expr_depth - 1)}; }}")
        else:
            methods.append(f"get {m}() {{ return {_random_expr(r, expr_depth - 1)}; }}")
    return f"class {cname}{base} {{ {' '.join(methods)} }}"


def _random_switch(r: random.Random, expr_depth: int, stmt_depth: int) -> str:
    expr = _random_expr(r, expr_depth - 1)
    cases = []
    for _ in range(r.randint(1, 2)):
        cases.append(f"case {_random_number(r)}: {_random_simple_stmt(r, stmt_depth - 1)} break;")
    if r.random() < 0.5:
        cases.append(f"default: {_random_simple_stmt(r, stmt_depth - 1)}")
    return f"switch ({expr}) {{ {' '.join(cases)} }}"


def _random_simple_stmt(r: random.Random, stmt_depth: int) -> str:
    expr_depth = MAX_EXPR_DEPTH
    # If depth exhausted, use simple statements only
    if stmt_depth <= 0:
        return f"{_random_expr(r, 1)};"
    pick = r.random()
    if pick < 0.18:
        return _random_var_decl(r, expr_depth)
    if pick < 0.32:
        return _random_if(r, expr_depth, stmt_depth)
    if pick < 0.44:
        return _random_loop(r, expr_depth, stmt_depth)
    if pick < 0.54:
        return _random_try(r, expr_depth, stmt_depth)
    if pick < 0.64:
        return _random_switch(r, expr_depth, stmt_depth)
    if pick < 0.76:
        return f"{_random_expr(r, expr_depth)};"
    if pick < 0.86:
        return _random_func_decl(r, expr_depth, stmt_depth)
    if pick < 0.94:
        return _random_class(r, expr_depth, stmt_depth)
    return f"throw new Error({_random_string_literal(r)});"


def _prologue_variants(r: random.Random) -> List[str]:
    items = []
    if r.random() < 0.5:
        items.append("\"use strict\";\n")
    if r.random() < 0.7:
        items.append("function __sum(a,b){return a+b;}\n")
    if r.random() < 0.4:
        items.append("const __data = [1,2,3].map(x=>x*2);\n")
    return items


def _epilogue_variants(r: random.Random) -> List[str]:
    items = []
    if r.random() < 0.5:
        items.append("new Promise((res,rej)=>{res(42)}).then(x=>x+1);\n")
    if r.random() < 0.3:
        items.append("let r=/a+/.test('baaa');\n")
    if r.random() < 0.5:
        items.append("JSON.stringify({k:'v', n: 1});\n")
    return items


def _build_program(r: random.Random, target_size: int) -> str:
    parts: List[str] = []
    parts.extend(_prologue_variants(r))
    # generate several top-level statements
    for _ in range(r.randint(5, 10)):
        parts.append(_random_simple_stmt(r, MAX_STMT_DEPTH))
        parts.append("\n")
        if sum(len(p) for p in parts) > target_size:
            break
    parts.extend(_epilogue_variants(r))
    program = ''.join(parts)
    if not program.strip():
        program = "let a=1+2; a;\n"
    return program


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    target = r.randint(256, min(2048, MAX_SIZE))
    prog = _build_program(r, target)
    enc = prog.encode('utf-8')
    if len(enc) > MAX_SIZE:
        trimmed = enc[:MAX_SIZE]
        s = trimmed.decode('utf-8', errors='ignore')
        if not s.endswith(('\n',';','}')):
            s += ';\n'
        enc = s.encode('utf-8')
    return enc
